1	import type { Port, VesselClass } from "@harbor/dispatch/types";
2	import { PORTS, VESSEL_CLASSES } from "@harbor/dispatch/generated/registry";
3	import { normaliseLocode } from "@harbor/dispatch/ports/locode";
4	
5	export function portByCode(code: string): Port | undefined {
6	  const key = normaliseLocode(code);
7	  return PORTS.find((p) => p.code === key);
8	}
9	
10	export function portsInCountry(country: string): Port[] {
11	  const cc = country.trim().toUpperCase();
12	  return PORTS.filter((p) => p.country === cc);
13	}
14	
15	export function vesselClass(name: string): VesselClass | undefined {
16	  const key = name.trim().toLowerCase();
17	  return VESSEL_CLASSES.find((v) => v.name.toLowerCase() === key);
18	}
19	
20	export function classesForPort(port: Port): VesselClass[] {
21	  return VESSEL_CLASSES.filter((v) => v.draftM <= port.maxDraftM);
22	}
23

